import axios from 'axios';

const API_URL = 'http://localhost:5000/api';

// Create axios instance with default config
const api = axios.create({
  baseURL: API_URL,
  timeout: 30000, // 30 seconds timeout
  headers: {
    'Content-Type': 'application/json',
  },
});

// Add request interceptor for debugging
api.interceptors.request.use(
  (config) => {
    console.log('API Request:', config.method?.toUpperCase(), config.url);
    return config;
  },
  (error) => {
    console.error('API Request Error:', error);
    return Promise.reject(error);
  }
);

// Add response interceptor for error handling
api.interceptors.response.use(
  (response) => {
    return response;
  },
  (error) => {
    if (error.code === 'ECONNREFUSED' || error.message.includes('Network Error')) {
      console.error('Backend server connection failed. Is the Flask server running on port 5000?');
      error.message = 'Cannot connect to backend server. Please ensure the Flask server is running on http://localhost:5000';
    }
    return Promise.reject(error);
  }
);

// Test backend connection
export const testConnection = async () => {
  try {
    const response = await axios.get(`${API_URL}/health`, { timeout: 5000 });
    return { success: true, data: response.data };
  } catch (error) {
    if (error.code === 'ECONNREFUSED' || error.message.includes('Network Error')) {
      return { 
        success: false, 
        error: 'Backend server is not running. Please start the Flask server on port 5000.' 
      };
    }
    return { success: false, error: error.message };
  }
};

export default api;
export { API_URL };
